sp_CancelarPedido	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_CancelarPedido`(p_idPedido INT, p_idUsuario INT)\nBEGIN\n\n    CALL sp_DevolverEstoquePedido(p_idPedido, p_idUsuario);\n\n\n\n    UPDATE Pedido SET statusPedido_id = 6 WHERE idPedido = p_idPedido;\n\n\n\n    INSERT INTO PedidoStatusHistorico (idPedido, statusPedido_id, idUsuario, dthAlteracao, observacao)\n\n    VALUES (p_idPedido, 6, p_idUsuario, CONVERT_TZ(NOW(), '+00:00', '-03:00'), 'Pedido cancelado');\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
